import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
/* eslint-disable */
export default {
  props: {
    bookslotview: Boolean,
    sloatitems: Array,
    selectedValue: String
  },
  data() {
    return {
      loading: false
    };
  },
  computed: {
    filteredBookings() {
      return this.sloatitems.filter(booking => booking.booked_user && booking.booked_user.user_name) // Filter bookings with a booked user
      .map(booking => ({
        booking_category_name: booking.booked_user.booking_category_name,
        user_name: booking.booked_user.user_name,
        booking_comments: booking.booked_user.booking_comments,
        s_time: booking.s_time,
        e_time: booking.e_time
      }));
    }
  },
  watch: {
    bookslotview: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    formatDateToLongForm(dateString) {
      const date = new Date(dateString);
      const day = date.getDate();
      const month = date.toLocaleString("default", {
        month: "long"
      });
      const weekday = date.toLocaleString("default", {
        weekday: "long"
      });
      return `${day} ${month} ${weekday}`;
    }
  }
};
